<script>
    const dateInput = document.querySelector('[data-date-mask]');
    const formatDate = (value) => {
        const digits = value.replace(/\D/g, '').slice(0, 8);
        if (digits.length <= 2) return digits;
        if (digits.length <= 4) return `${digits.slice(0, 2)}/${digits.slice(2)}`;
        return `${digits.slice(0, 2)}/${digits.slice(2, 4)}/${digits.slice(4)}`;
    };
    dateInput?.addEventListener('input', (event) => { event.currentTarget.value = formatDate(event.currentTarget.value); });
    const moneyInput = document.querySelector('[data-money-mask]');
    const formatMoney = (value) => value.replace(/\D/g, '').slice(0, 10).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
    if (moneyInput) {
        moneyInput.value = formatMoney(moneyInput.value);
        moneyInput.addEventListener('input', (event) => { event.currentTarget.value = formatMoney(event.currentTarget.value); });
    }
    document.getElementById('feol-form')?.addEventListener('submit',()=>{const b=document.getElementById('submit-button');b.disabled=true;b.textContent='Đang kiểm tra hồ sơ...'});
</script>
